param([switch]$Aplicar)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'package.json')) { throw 'Ejecuta desde la raiz de LERABOT.' }
Write-Host "LERABOT FASE 5: Auditoria de Trading - frontend y Lambda de solo lectura"
Write-Host 'No usa AWS CLI, no consulta DynamoDB, no hace git push ni deploy.'
Write-Host "Archivos:"
Write-Host '  src/modulos/auditoria/tipos.ts'
Write-Host '  src/modulos/auditoria/servicio.ts'
Write-Host '  src/modulos/auditoria/AuditoriaView.vue'
Write-Host '  backend/funciones/auditoria/index.mjs'
Write-Host '  docs/FASE5_AUDITORIA.md'
Write-Host '  src/nucleo/rutas/index.ts'
Write-Host '  src/compartido/componentes/MenuLateral.vue'
if (-not $Aplicar) { Write-Host 'PREVISUALIZACION. Para escribir: -Aplicar'; exit 0 }
$utf8 = New-Object System.Text.UTF8Encoding($false)
$respaldo = Join-Path $env:TEMP ('LERABOT-F5-'+(Get-Date -Format 'yyyyMMdd-HHmmss'))
Write-Host ('Respaldos: '+$respaldo)
$ruta = 'src/modulos/auditoria/tipos.ts'
$destino = Join-Path (Get-Location).Path $ruta
New-Item -ItemType Directory -Force (Split-Path $destino) | Out-Null
if (Test-Path $destino) { $copia = Join-Path $respaldo $ruta; New-Item -ItemType Directory -Force (Split-Path $copia) | Out-Null; Copy-Item $destino $copia -Force }
$contenido = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[IO.File]::WriteAllText($destino, $contenido, $utf8)
Write-Host ('OK '+$ruta)
$ruta = 'src/modulos/auditoria/servicio.ts'
$destino = Join-Path (Get-Location).Path $ruta
New-Item -ItemType Directory -Force (Split-Path $destino) | Out-Null
if (Test-Path $destino) { $copia = Join-Path $respaldo $ruta; New-Item -ItemType Directory -Force (Split-Path $copia) | Out-Null; Copy-Item $destino $copia -Force }
$contenido = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[IO.File]::WriteAllText($destino, $contenido, $utf8)
Write-Host ('OK '+$ruta)
$ruta = 'src/modulos/auditoria/AuditoriaView.vue'
$destino = Join-Path (Get-Location).Path $ruta
New-Item -ItemType Directory -Force (Split-Path $destino) | Out-Null
if (Test-Path $destino) { $copia = Join-Path $respaldo $ruta; New-Item -ItemType Directory -Force (Split-Path $copia) | Out-Null; Copy-Item $destino $copia -Force }
$contenido = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[IO.File]::WriteAllText($destino, $contenido, $utf8)
Write-Host ('OK '+$ruta)
$ruta = 'backend/funciones/auditoria/index.mjs'
$destino = Join-Path (Get-Location).Path $ruta
New-Item -ItemType Directory -Force (Split-Path $destino) | Out-Null
if (Test-Path $destino) { $copia = Join-Path $respaldo $ruta; New-Item -ItemType Directory -Force (Split-Path $copia) | Out-Null; Copy-Item $destino $copia -Force }
$contenido = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[IO.File]::WriteAllText($destino, $contenido, $utf8)
Write-Host ('OK '+$ruta)
$ruta = 'docs/FASE5_AUDITORIA.md'
$destino = Join-Path (Get-Location).Path $ruta
New-Item -ItemType Directory -Force (Split-Path $destino) | Out-Null
if (Test-Path $destino) { $copia = Join-Path $respaldo $ruta; New-Item -ItemType Directory -Force (Split-Path $copia) | Out-Null; Copy-Item $destino $copia -Force }
$contenido = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[IO.File]::WriteAllText($destino, $contenido, $utf8)
Write-Host ('OK '+$ruta)
$ruta = 'src/nucleo/rutas/index.ts'
$destino = Join-Path (Get-Location).Path $ruta
New-Item -ItemType Directory -Force (Split-Path $destino) | Out-Null
if (Test-Path $destino) { $copia = Join-Path $respaldo $ruta; New-Item -ItemType Directory -Force (Split-Path $copia) | Out-Null; Copy-Item $destino $copia -Force }
$contenido = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[IO.File]::WriteAllText($destino, $contenido, $utf8)
Write-Host ('OK '+$ruta)
$ruta = 'src/compartido/componentes/MenuLateral.vue'
$destino = Join-Path (Get-Location).Path $ruta
New-Item -ItemType Directory -Force (Split-Path $destino) | Out-Null
if (Test-Path $destino) { $copia = Join-Path $respaldo $ruta; New-Item -ItemType Directory -Force (Split-Path $copia) | Out-Null; Copy-Item $destino $copia -Force }
$contenido = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[IO.File]::WriteAllText($destino, $contenido, $utf8)
Write-Host ('OK '+$ruta)
Write-Host 'LISTO. Verifica node --check backend/funciones/auditoria/index.mjs; npm run type-check; npm run build'
Write-Host 'Para AWS revisa docs/FASE5_AUDITORIA.md'
